import fs from 'fs';

const path = 'src/App.jsx';
let app = fs.readFileSync(path, 'utf8');
const start = app.indexOf('const TIPS_DATA = [');
if (start < 0) throw new Error('TIPS_DATA not found');
const end = app.indexOf('\n];', start);
if (end < 0) throw new Error('TIPS_DATA closing bracket not found');
const block = app.slice(start, end);

const categories = ['dog','cat','health','life','food','training','safety','grooming'];
const ids = [...block.matchAll(/id:\s*"t(\d+)"/g)].map(m => Number(m[1]));
const titles = new Set([...block.matchAll(/title:\s*\{\s*ko:\s*"([^"]+)"/g)].map(m => m[1]));
if (!ids.length) throw new Error('PetInfo IDs not found');
const maxId = Math.max(...ids);
if (maxId < 306) throw new Error(`Expected dataset through at least t306, found t${maxId}`);

const candidates = [
  {category:'dog',featured:true,titleKo:'산책 전후로 물 섭취 상태를 확인해요',titleEn:'Check water access around walks',summaryKo:'산책 전후에 물을 마실 수 있는지 확인하면 더운 날 탈수 예방에 도움이 돼요.',summaryEn:'Making water available before and after walks can help reduce dehydration risk.',bodyKo:'특히 더운 날이나 활동량이 많은 날에는 산책 전후로 신선한 물을 준비하세요. 한 번에 과도하게 마시게 하기보다 편하게 접근할 수 있도록 두고, 심한 헐떡임이나 무기력 등 이상이 있으면 즉시 쉬게 하고 상태를 확인하세요.',bodyEn:'On warm or active days, make fresh water available before and after walks. Let your dog drink comfortably rather than forcing large amounts at once, and stop activity if severe panting or lethargy appears.'},
  {category:'dog',featured:false,titleKo:'산책 중 갑자기 멈추면 억지로 끌지 않아요',titleEn:'Do not drag a dog that suddenly stops on walks',summaryKo:'갑자기 멈추는 행동에는 피로, 두려움, 통증 같은 이유가 있을 수 있어요.',summaryEn:'Sudden stopping can reflect fatigue, fear, discomfort, or pain.',bodyKo:'반려견이 갑자기 걷기를 거부하면 먼저 주변 자극과 발바닥, 다리 상태를 확인하세요. 계속 걷게 강요하기보다 잠시 쉬고, 절뚝거림이나 통증 반응이 지속되면 동물병원에 상담하세요.',bodyEn:'If your dog suddenly refuses to continue, check the surroundings, paws, and legs. Allow a pause instead of forcing movement, and seek veterinary advice if limping or pain persists.'},
  {category:'cat',featured:true,titleKo:'고양이 창가 쉼터는 직사광선과 온도를 함께 살펴요',titleEn:'Check heat and sunlight at cat window perches',summaryKo:'햇볕 드는 창가는 좋아할 수 있지만 한낮에는 과열되지 않게 확인해요.',summaryEn:'Sunny window spots can be appealing, but they should not become excessively hot.',bodyKo:'창가 쿠션이나 해먹이 강한 직사광선을 오래 받는다면 다른 서늘한 쉼터도 함께 마련하세요. 유리창 주변 온도가 높아지는 시간에는 커튼이나 블라인드로 열을 줄여 주세요.',bodyEn:'If a window bed receives strong direct sun for long periods, provide a cooler alternative. Use curtains or blinds when the area becomes too warm.'},
  {category:'cat',featured:false,titleKo:'고양이 화장실 모래 높이는 갑자기 크게 바꾸지 않아요',titleEn:'Avoid sudden major changes in litter depth',summaryKo:'익숙한 화장실 환경을 급격히 바꾸면 사용을 망설일 수 있어요.',summaryEn:'Large sudden litter changes can make some cats reluctant to use the box.',bodyKo:'모래 종류나 깊이를 바꿀 때는 기존 환경과 섞어 서서히 적응시키는 방법을 고려하세요. 화장실 이용 횟수가 급격히 줄거나 배뇨 이상이 보이면 환경 문제로만 판단하지 말고 진료를 받아야 합니다.',bodyEn:'When changing litter type or depth, consider a gradual transition. A sudden drop in litter-box use or abnormal urination warrants veterinary attention rather than assuming it is only behavioral.'},
  {category:'health',featured:true,titleKo:'평소 호흡수를 편안히 쉴 때 기록해두면 좋아요',titleEn:'Know your pet’s resting breathing pattern',summaryKo:'편안히 쉬는 상태의 평소 호흡을 알아두면 갑작스러운 변화를 알아차리기 쉬워요.',summaryEn:'Knowing normal resting breathing makes unusual changes easier to notice.',bodyKo:'잠들었거나 편안히 누워 있을 때의 호흡 패턴을 평소 관찰해두세요. 힘겹게 숨 쉬거나 입을 벌리고 호흡하는 등 평소와 다른 모습이 지속되면 신속히 동물병원에 문의하세요.',bodyEn:'Observe your pet’s usual breathing while asleep or calmly resting. Persistent labored breathing, open-mouth breathing, or a marked change from normal requires prompt veterinary attention.'},
  {category:'health',featured:false,titleKo:'상처를 핥는 행동이 계속되면 보호 장비를 검토해요',titleEn:'Consider protection if wound licking continues',summaryKo:'지속적인 핥기는 회복 중인 피부를 다시 자극할 수 있어요.',summaryEn:'Repeated licking can irritate healing skin and delay recovery.',bodyKo:'수술 부위나 상처를 계속 핥는다면 담당 수의사의 안내에 따라 넥카라나 보호복 같은 방법을 사용할 수 있어요. 붓기, 진물, 악취, 출혈이 보이면 바로 상태를 확인받으세요.',bodyEn:'If your pet repeatedly licks a surgical site or wound, use an e-collar or recovery garment if recommended by the veterinary team. Swelling, discharge, odor, or bleeding should be checked promptly.'},
  {category:'life',featured:true,titleKo:'집 안 미끄러운 구간에는 작은 매트를 활용해요',titleEn:'Add traction on slippery indoor paths',summaryKo:'자주 지나는 미끄러운 바닥에 매트를 두면 이동이 더 안정적일 수 있어요.',summaryEn:'Adding traction to frequently used slippery areas can make movement safer.',bodyKo:'현관, 복도, 소파 주변처럼 자주 지나는 곳이 미끄럽다면 움직이지 않는 매트를 배치해 보세요. 특히 어린 반려동물이나 노령동물이 급하게 뛰지 않도록 동선을 정리하는 것이 좋아요.',bodyEn:'Place non-slip mats in commonly used slippery areas such as hallways or near furniture. Clear pathways are especially helpful for young or older pets.'},
  {category:'life',featured:false,titleKo:'외출 후에는 반려동물이 안정할 시간을 먼저 줘요',titleEn:'Allow quiet decompression after busy outings',summaryKo:'낯선 장소나 긴 외출 뒤에는 바로 놀이를 이어가기보다 쉴 시간을 주세요.',summaryEn:'After stimulating outings, quiet recovery time can help pets settle.',bodyKo:'병원, 여행, 긴 산책처럼 자극이 많았던 일정 뒤에는 익숙한 물과 침구가 있는 조용한 공간에서 쉬게 해주세요. 피곤하거나 예민해 보일 때는 추가 훈련이나 놀이를 줄이는 것이 좋아요.',bodyEn:'After a vet visit, travel, or a long walk, offer a quiet familiar place with water and bedding. Reduce extra training or play if your pet appears tired or overstimulated.'},
  {category:'food',featured:true,titleKo:'새 사료는 기존 사료와 서서히 섞어 바꿔요',titleEn:'Transition to new food gradually',summaryKo:'갑작스러운 사료 변경보다 며칠에 걸쳐 비율을 조절하는 편이 소화 부담을 줄일 수 있어요.',summaryEn:'Gradual food transitions can reduce digestive upset compared with abrupt changes.',bodyKo:'특별한 의료 지시가 없다면 기존 사료와 새 사료를 며칠에 걸쳐 비율을 바꾸며 적응시키세요. 구토나 설사, 식욕 저하가 반복되면 변경을 중단하고 수의사에게 상담하세요.',bodyEn:'Unless a veterinarian advises otherwise, gradually increase the proportion of new food over several days. Repeated vomiting, diarrhea, or poor appetite should prompt veterinary advice.'},
  {category:'food',featured:false,titleKo:'습식사료 남은 양은 오래 상온에 두지 않아요',titleEn:'Do not leave leftover wet food out too long',summaryKo:'먹다 남은 습식사료는 제품 안내에 맞춰 빠르게 정리해요.',summaryEn:'Handle leftover wet food promptly according to storage guidance.',bodyKo:'반려동물이 먹고 남긴 습식사료를 장시간 상온에 두지 말고 제품 보관 지침을 따르세요. 재급여할 경우 냄새와 상태를 확인하고 의심되면 버리는 것이 안전합니다.',bodyEn:'Do not leave uneaten wet food at room temperature for extended periods. Follow product storage directions and discard food that smells or looks unusual.'},
  {category:'training',featured:true,titleKo:'보상은 원하는 행동 직후에 바로 줘요',titleEn:'Deliver rewards immediately after the desired behavior',summaryKo:'행동과 보상 사이가 짧을수록 무엇을 잘했는지 이해하기 쉬워요.',summaryEn:'A short delay between behavior and reward makes learning clearer.',bodyKo:'앉기, 기다리기, 이름 부르면 보기처럼 원하는 행동이 나온 직후 칭찬이나 간식을 주세요. 시간이 많이 지난 뒤 보상하면 다른 행동과 연결될 수 있으니 타이밍을 일정하게 유지하세요.',bodyEn:'Reward behaviors such as sit, wait, or responding to a name immediately after they occur. Consistent timing helps the pet understand which behavior earned the reward.'},
  {category:'training',featured:false,titleKo:'훈련이 잘 안 되는 날에는 난이도를 한 단계 낮춰요',titleEn:'Lower the difficulty on hard training days',summaryKo:'실패가 반복되면 더 쉬운 조건으로 돌아가 성공 경험을 만들어줘요.',summaryEn:'If failures repeat, return to easier conditions and rebuild success.',bodyKo:'주변 자극이 많거나 집중이 떨어지는 날에는 거리, 시간, 행동 난이도를 낮춰 주세요. 쉬운 단계에서 성공하면 보상하고 다음 기회에 조금씩 다시 난이도를 올리는 것이 좋아요.',bodyEn:'When distractions are high or focus is poor, reduce distance, duration, or task difficulty. Reward success at the easier level and increase difficulty gradually later.'},
  {category:'safety',featured:true,titleKo:'여름철 차량 안에는 잠깐이라도 혼자 두지 않아요',titleEn:'Never leave pets alone in a warm parked car',summaryKo:'짧은 시간에도 차량 내부 온도는 빠르게 올라 위험할 수 있어요.',summaryEn:'Vehicle interiors can heat rapidly even during short stops.',bodyKo:'창문을 조금 열어두는 것만으로는 안전하지 않을 수 있으므로 더운 날 주차된 차량에 반려동물을 혼자 두지 마세요. 이동 중에도 냉방과 환기 상태를 수시로 확인하세요.',bodyEn:'Cracking a window may not keep a parked car safe. Do not leave pets unattended in warm vehicles, and monitor cooling and ventilation during travel.'},
  {category:'safety',featured:false,titleKo:'충전 케이블과 전선은 씹지 못하게 정리해요',titleEn:'Keep charging cables and cords out of chewing reach',summaryKo:'노출된 전선은 감전이나 화상 위험이 있어 정리해두는 것이 좋아요.',summaryEn:'Exposed electrical cords can pose shock and burn hazards if chewed.',bodyKo:'휴대폰 충전선과 멀티탭, 가전 전선을 반려동물이 닿기 어려운 곳에 정리하고 손상된 전선은 사용하지 마세요. 감전이 의심되면 겉으로 멀쩡해 보여도 즉시 동물병원에 문의하세요.',bodyEn:'Route charging cables, power strips, and appliance cords out of reach and replace damaged cords. If electrical injury is suspected, seek veterinary advice even if there is no obvious external injury.'},
  {category:'grooming',featured:true,titleKo:'눈 주변 털은 눈을 찌르지 않는지 자주 확인해요',titleEn:'Check that facial hair is not irritating the eyes',summaryKo:'눈 주변 긴 털이 각막을 자극하지 않도록 상태를 살펴요.',summaryEn:'Long facial hair should not rub against or irritate the eyes.',bodyKo:'눈 주변 털이 안쪽으로 말려 들어가거나 눈을 계속 건드리는지 확인하세요. 눈물, 충혈, 눈을 자주 비비는 행동이 있으면 미용만으로 해결하려 하지 말고 동물병원에서 상태를 확인하세요.',bodyEn:'Check whether facial hair curls toward or repeatedly touches the eyes. Tearing, redness, or frequent rubbing should be evaluated by a veterinarian rather than treated as a grooming issue alone.'},
  {category:'grooming',featured:false,titleKo:'목욕 후에는 피부 접히는 부위도 충분히 말려요',titleEn:'Dry skin folds thoroughly after bathing',summaryKo:'주름이나 발가락 사이처럼 습기가 남기 쉬운 부위까지 부드럽게 말려요.',summaryEn:'Dry moisture-prone areas such as skin folds and between the toes thoroughly.',bodyKo:'목욕 뒤에는 겨드랑이, 발가락 사이, 피부 주름처럼 습기가 남기 쉬운 곳을 확인해 부드럽게 말려 주세요. 붉음, 냄새, 진물이 반복되면 피부 상태를 진료받는 것이 좋습니다.',bodyEn:'After bathing, gently dry areas that trap moisture, including skin folds, armpits, and between toes. Recurrent redness, odor, or discharge should be assessed by a veterinarian.'}
];

const fresh = candidates.filter(item => !titles.has(item.titleKo));
if (!fresh.length) {
  console.log('No new PetInfo items to add');
  process.exit(0);
}
if (fresh.length !== 16) throw new Error(`Expected 16 unique PetInfo candidates, got ${fresh.length}`);
if (new Set(fresh.map(x => x.category)).size !== categories.length) throw new Error('PetInfo category coverage incomplete');

let nextId = maxId + 1;
const lines = fresh.map(item => `\n  { id: "t${nextId++}", category: "${item.category}", featured: ${item.featured},\n    title: { ko: ${JSON.stringify(item.titleKo)}, en: ${JSON.stringify(item.titleEn)} },\n    summary: { ko: ${JSON.stringify(item.summaryKo)}, en: ${JSON.stringify(item.summaryEn)} },\n    body: { ko: ${JSON.stringify(item.bodyKo)}, en: ${JSON.stringify(item.bodyEn)} }, sourceDate: "2026-08-26" },`).join('');
app = app.slice(0, end) + lines + app.slice(end);
fs.writeFileSync(path, app);
console.log(`Added ${fresh.length} PetInfo items through t${nextId - 1}`);
